python3 - <<'PY'
p='src/types/checker/functions/resolution/specialization.rs'
s=open(p).read()
old = """                let by_ref_array =
                    Self::by_ref_array_param_type(&param_types[seen_idx].1, &actual_ty)
                        .filter(|_| by_ref_param);
                if let Some(widened) = by_ref_array {
                    self.param_specialization_seen.insert(key);
                    if param_types[seen_idx].1 != widened {
                        param_types[seen_idx].1 = widened;
                        changed = true;
                    }
                } else if Self::is_generic_array_hint(&param_types[seen_idx].1)"""
new = """                // A by-reference parameter whose BODY widened its element type keeps that
                // widened type: it is what the caller's storage now holds. The narrowing
                // below would undo it on the next call and hand a body compiled for raw
                // slots an array of boxes.
                let by_ref_widened = by_ref_param
                    && matches!(
                        param_types[seen_idx].1.codegen_repr(),
                        PhpType::Array(ref elem) if elem.codegen_repr() == PhpType::Mixed
                    );
                if by_ref_widened {
                    self.param_specialization_seen.insert(key);
                } else if Self::is_generic_array_hint(&param_types[seen_idx].1)"""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))
print('specialization guard narrowed')
